package it.penny.api.margins;
import it.penny.api.PennyApplication;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import java.util.*;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(classes=PennyApplication.class)
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="PENNY_TEST_JDBC_URL",matches=".+")
class MarginsIntegrationTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->System.getenv("PENNY_TEST_JDBC_URL")+"?currentSchema=margins_api");p.add("spring.datasource.username",()->System.getenv("PENNY_TEST_DB_USER"));p.add("spring.datasource.password",()->System.getenv("PENNY_TEST_DB_PASSWORD"));p.add("spring.flyway.schemas",()->"margins_api");p.add("spring.jpa.hibernate.ddl-auto",()->"validate");}
 @Autowired JdbcTemplate db;@Autowired MarginService s;@Autowired MarginsController controller;
 final UsernamePasswordAuthenticationToken admin=new UsernamePasswordAuthenticationToken("margin-admin@test.invalid","unused",List.of());
 @BeforeEach void setup(){db.execute("TRUNCATE penny_margin_profiles,penny_sales,penny_catalog_products,penny_customers,penny_users RESTART IDENTITY CASCADE");db.update("INSERT INTO penny_users(email,full_name,password_hash,must_change_password) VALUES (?,'Admin','unused',false)",admin.getName());db.update("INSERT INTO penny_user_roles SELECT u.id,r.id FROM penny_users u CROSS JOIN penny_roles r WHERE u.email=? AND r.code='ADMIN'",admin.getName());db.update("INSERT INTO penny_customers(id,kind,name,lifecycle_status) VALUES (1,'COMPANY','Alpha','CUSTOMER')");db.update("INSERT INTO penny_margin_profiles(id,name,components) VALUES (1,'Software','[\"One\",\"Two\",\"Three\",\"Supplier\"]')");db.execute("SELECT setval(pg_get_serial_sequence('penny_margin_profiles','id'),1)");db.update("INSERT INTO penny_catalog_products(id,code,name,origin,category,margin_management,margin_profile_id) VALUES (1,'MARG','Margin software','INTERNAL','SOFTWARE','AUTOMATIC',1)");for(var e:Map.of("One",5,"Two",15,"Three",12,"Supplier",3).entrySet())db.update("INSERT INTO penny_margin_rules(profile_id,name,component,calculation,value,sign,conditions,valid_from,valid_to,status,created_by) VALUES (1,?,?,'PERCENT',?,?,?::jsonb,'2026-02-07','2027-02-06','ACTIVE',?)",e.getKey(),e.getKey(),e.getValue(),e.getKey().equals("Supplier")?-1:1,e.getKey().equals("One")?"{\"operationType\":[\"NEW_LICENSE\",\"FIRST_RENEWAL\"]}":e.getKey().equals("Two")?"{\"operationType\":\"NEW_LICENSE\"}":"{}",admin.getName());db.update("INSERT INTO penny_sales(id,customer_id,catalog_product_id,product_code,product_name,origin,category,sold_on,quantity,unit_price,business) VALUES (1,1,1,'MARG','Margin software','INTERNAL','SOFTWARE','2026-10-29',1,1000,'{\"operationType\":\"NEW_LICENSE\"}')");}
 @Test void snapshotsRecognitionsAdjustmentsCancellationsAndReevaluationRetainHistory(){s.snapshot(1,admin);assertEquals("290.00",controller.report(1L,admin).get("theoretical"));assertEquals("0.00",controller.report(1L,admin).get("recognized"));long id=db.queryForObject("SELECT id FROM penny_margin_snapshots WHERE component='Two'",Long.class);s.change(id,"CONFIRMED",null,null,admin);s.change(id,"ADJUSTED",new BigDecimal("-50"),"Supplier correction",admin);assertEquals("100.00",controller.report(1L,admin).get("recognized"));assertThrows(Exception.class,()->s.change(id,"ADJUSTED",BigDecimal.ONE,"",admin));s.change(id,"CANCELLED",null,"Withdrawn",admin);assertEquals("0.00",controller.report(1L,admin).get("recognized"));assertEquals(new BigDecimal("150.00"),db.queryForObject("SELECT calculated FROM penny_margin_snapshots WHERE id=?",BigDecimal.class,id));s.reevaluate(1,"Authorized revision",admin);assertEquals(8,db.queryForObject("SELECT count(*) FROM penny_margin_snapshots",Integer.class));assertEquals("290.00",controller.report(1L,admin).get("theoretical"));assertThrows(Exception.class,()->s.change(id,"CONFIRMED",null,null,admin));}
 @Test void deterministicPriorityAndFrozenHistoricalRule(){s.snapshot(1,admin);long rule=db.queryForObject("SELECT id FROM penny_margin_rules WHERE component='Two'",Long.class);controller.close(rule,new MarginsController.RuleChange(java.time.LocalDate.of(2026,10,31),"New supplier agreement",null),admin);db.update("INSERT INTO penny_margin_rules(profile_id,previous_id,name,component,calculation,value,sign,valid_from,status,created_by,priority) VALUES (1,?,'New Two','Two','PERCENT',13,1,'2026-11-01','ACTIVE',?,10)",rule,admin.getName());assertEquals("290.00",controller.report(1L,admin).get("theoretical"));assertEquals(1,db.queryForObject("SELECT count(*) FROM penny_margin_rule_audit",Integer.class));db.update("INSERT INTO penny_margin_rules(profile_id,name,component,calculation,value,sign,valid_from,status,created_by,priority) VALUES (1,'Override','Two','FIXED',20,1,'2026-01-01','ACTIVE',?,20)",admin.getName());s.reevaluate(1,"Apply priority override",admin);assertEquals("160.00",controller.report(1L,admin).get("theoretical"));}
 @Test void controllerReadsProfilesAndRulesThroughTransactionalServiceProxy(){
  assertEquals(1,((List<?>)controller.profiles(admin).get("items")).size());
  assertEquals(4,((List<?>)controller.rules(admin).get("items")).size());
  var created=controller.profile(new MarginsController.Profile("Hardware",List.of("Fixed")),admin);
  assertNotNull(created.get("id"));
 }
 @Test void permissionRequiredForReevaluationAndRecognition(){var outsider=new UsernamePasswordAuthenticationToken("unknown@test.invalid","unused",List.of());assertThrows(Exception.class,()->controller.report(null,outsider));assertThrows(Exception.class,()->s.reevaluate(1,"Unauthorized",outsider));assertEquals(0,db.queryForObject("SELECT count(*) FROM penny_margin_snapshots",Integer.class));}
}
